import java.util.List;

public class ActionType {

    private List<ActionConfigurationProperty> actionConfigurationProperties;

    /**
     * Adds or modifies configuration properties for this action type.
     *
     * @param actionConfigurationProperties the array of properties to add
     * @return this ActionType instance to support method chaining
     */
    public ActionType withActionConfigurationProperties(
            ActionConfigurationProperty[] actionConfigurationProperties) {

        if (this.actionConfigurationProperties == null) {
            this.actionConfigurationProperties = new ArrayList<>();
        }

        if (actionConfigurationProperties != null) {
            for (ActionConfigurationProperty prop : actionConfigurationProperties) {
                this.actionConfigurationProperties.add(prop);
            }
        }

        return this;
    }
}
